   FormClosed+=(s,e)=>{if(cover.Image!=null)cover.Image.Dispose();thumbs.Dispose();guidance.Dispose();};UpdateSelection();
  }
  ImportCandidate Selected{get{return list.SelectedItems.Count==1?list.SelectedItems[0].Tag as ImportCandidate:null;}}
  string Hash(ImportCandidate c){return c==null||c.Check==null?null:c.Check.Sha256;}
  WallpaperItem Registered(ImportCandidate c){var hash=Hash(c);return !PackageAnalysis.HashText(hash)?null:owner.library.Doc.Items.FirstOrDefault(x=>x.RegisteredSha256==hash);}
  internal string ResourceState(ImportCandidate c){return Registered(c)!=null?"已入库":c.NewlyDiscovered?"新发现":"历史资源";}
  internal string PlaybackState(ImportCandidate c){var saved=Registered(c);string hash=Hash(c);return saved==null?"尚未验证":saved.DesktopConfirmedSha256==hash?"已有桌面记录":saved.PreviewConfirmedSha256==hash||saved.Id=="builtin-317495"&&hash==Common.CwpHash?"已有窗口确认":"尚未验证";}
  internal string CandidateRowState(ImportCandidate c){switch(c.Check==null?"queued":c.Check.State){case "checking":return "检查中";case "passed":return "通过";case "unknown":return "结构未知";case "failed":return "检查失败";case "cancelled":return "已取消";case "waiting":return "等待文件稳定";default:return "排队";}}
  internal string CoverState(ImportCandidate c){if(c.Cover!=null&&c.Check!=null&&c.Check.CoverSha256!=null)return c.Check.CoverKind==PreviewCovers.Kind?"预览截图":c.Check.CoverKind==VideoCovers.Kind?"视频画面":"真实图片";if(c.Check==null||c.Check.State=="queued")return "排队读取";if(c.Check.State=="checking")return c.Check.Phase!=null&&c.Check.Phase.Contains("封面")?"读取中":"等待检查";if(c.Check.State=="cancelled")return "已取消";return c.Check.CoverReason!=null&&c.Check.CoverReason.Contains("失败")?"读取失败":"无可靠图片";}
  internal string CandidateState(ImportCandidate c){if(c==null)return "选择候选即可查看结果，无需逐项开始检查。";string state=CandidateRowState(c);if(c.Check==null||c.Check.State=="queued")return "已自动排队；检查与封面读取会逐项进行。";if(c.Check.State=="checking")return "正在检查："+c.Check.Phase;if(c.Check.State=="unknown")return "结构未知："+c.Check.Reason+"。保留候选与身份记录；当前窗口不能导入，需开发补充解析器或规则，重复检查不会增加支持。";if(c.Check.State=="passed")return "入库前检查通过，可主动导入。"+c.Check.Reason;return state+"："+c.Check.Reason+"\n发生阶段："+c.Check.Phase+"\n可用“重新检查此文件”重试。";}
  void ControlsState(){((SoftButton)import).Busy=copying;((SoftButton)refresh).Busy=scanning;((SoftButton)analyze).Busy=queueRunning;import.Enabled=!scanning&&!copying&&!queueRunning&&!closeRequested&&CandidateChecks.Passed(Selected);import.Text=copying?"正在导入…":queueRunning&&CandidateChecks.Passed(Selected)?"等待队列结束":"导入所选壁纸";analyze.Enabled=!scanning&&!copying&&!queueRunning&&!closeRequested&&Selected!=null&&(Selected.Check==null||Selected.Check.State!="unknown");refresh.Enabled=!scanning&&!copying&&!queueRunning&&!closeRequested;cancel.Text=copying?"取消导入":scanning||queueRunning?"取消检查":"关闭";progress.Style=scanning||queueRunning?ProgressBarStyle.Marquee:ProgressBarStyle.Blocks;}
  void UpdateRow(ListViewItem row){var c=(ImportCandidate)row.Tag;row.Text=c.Name+" · "+c.Id;string[] values={(c.Bytes/1048576.0).ToString("F1")+" MB",ResourceState(c),CandidateRowState(c),CoverState(c),PlaybackState(c)};for(int i=0;i<values.Length;i++)row.SubItems[i+1].Text=values[i];row.ToolTipText="ID："+c.Id+"\n"+c.Name+"\n"+CandidateState(c);}
  void Thumbnail(ListViewItem row){var c=(ImportCandidate)row.Tag;string key=c.Source;row.ImageKey="";if(c.Cover==null)return;try{using(var im=WallpaperLibrary.LoadCover(new WallpaperItem{CoverPath=c.Cover})){if(im!=null){int existing=thumbs.Images.IndexOfKey(key);if(existing>=0){thumbs.Images[existing]=im;thumbs.Images.SetKeyName(existing,key);}else thumbs.Images.Add(key,im);row.ImageKey=key;}}}catch{}}
  ListViewItem AddCandidate(ImportCandidate c){var row=new ListViewItem(new[]{"","","","","",""}){Tag=c};list.Items.Add(row);UpdateRow(row);Thumbnail(row);return row;}
  internal void UpdateSelection(){var c=Selected;ControlsState();if(cover.Image!=null){cover.Image.Dispose();cover.Image=null;}if(c!=null&&c.Cover!=null)try{using(var im=WallpaperLibrary.LoadCover(new WallpaperItem{CoverPath=c.Cover})){if(im!=null)cover.Image=new Bitmap(im);}}catch{}note.Text=c==null?CandidateState(null):("ID："+c.Id+"\n名称："+(c.NameSource==null?"暂未取得官方名称":"已保存官方本地名称")+"\n资源："+ResourceState(c)+"\n检查："+CandidateRowState(c)+"\n封面："+CoverState(c)+"\n播放："+PlaybackState(c)+"\n\n"+CandidateState(c)+"\n封面说明："+(c.CoverReason??"后台处理尚未完成")+"\n\nSHA-256："+(Hash(c)??"尚未完成")+"\n首次发现："+c.FirstDiscoveredAt+"\n记录更新时间："+c.RecordUpdatedAt+"\n以上不是官方下载时间。\n视频会自动截取开头可识别的一帧；未取得图片时会说明原因。").Replace("\n","\r\n");}
  internal async Task StopQueue(){queueStop=true;if(queueRunning&&owner.importOperation!=null)owner.importOperation.Cancel();foreach(ListViewItem row in list.Items){var c=(ImportCandidate)row.Tag;if(c.Check==null||c.Check.State=="queued"||c.Check.State=="waiting"){c.Check=new CandidateCheckResult{State="cancelled",Phase="排队",Reason="用户取消本次队列；未导入"};UpdateRow(row);}}var task=queueTask;if(task!=null)await task;}
  async Task RunOne(ListViewItem row,bool force){var c=(ImportCandidate)row.Tag;phase="核对本地记录";c.Check=new CandidateCheckResult{State="checking",Phase=phase};c.Cover=null;c.CoverReason="后台读取中";UpdateRow(row);UpdateSelection();owner.Write("candidate-check-start",new{id=c.Id,name=c.Name,source=c.Source,force=force,autoImport=false});
   try{var data=await owner.ImportJob(force?"recheck":"check",c,(p,b,t)=>{if(IsDisposed)return;phase=p;c.Check.Phase=p;status.Text="正在检查 "+(done+1)+" / "+total+" 项 · "+c.Name+" · "+p;UpdateRow(row);if(Object.ReferenceEquals(c,Selected))UpdateSelection();});row.Tag=Common.Json.Deserialize<ImportCandidate>(Common.Json.Serialize(data["candidate"]));OfficialNameStore.ApplySaved(new List<ImportCandidate>{(ImportCandidate)row.Tag});}
   catch(OperationCanceledException){c.Check.State="cancelled";c.Check.Reason="已取消；未导入";c.Check.Phase=phase;}
   catch(Exception ex){c.Check.State="failed";c.Check.Reason=ex.Message;c.Check.Phase=phase;}
   finally{if(!IsDisposed){UpdateRow(row);Thumbnail(row);UpdateSelection();var result=(ImportCandidate)row.Tag;if(result.Check.State=="failed")owner.RecordFault("check","检查本地候选",result.Check.Phase,result.Check.Reason,result,()=>{if(!IsDisposed&&!closeRequested&&!queueRunning&&!copying){row.Selected=true;var ignored=AnalyzeSelected();}});owner.Write("candidate-check-result",new{id=result.Id,name=result.Name,source=result.Source,state=result.Check.State,reason=result.Check.Reason,stage=result.Check.Phase,sha256=result.Check.Sha256,cacheHit=result.Check.CacheHit,hashedBytes=result.Check.HashedBytes,cover=result.Check.CoverMember,coverSha256=result.Check.CoverSha256,autoImport=false,autoPlay=false});}}}
  async Task RunQueue(){queueRunning=true;done=0;var pending=list.Items.Cast<ListViewItem>().Where(r=>{var c=(ImportCandidate)r.Tag;return c.Check==null||c.Check.State=="queued"||c.Check.State=="waiting";}).ToList();total=pending.Count;ControlsState();try{for(int i=0;i<pending.Count;i++){if(queueStop||owner.closing||closeRequested)break;var row=pending[i];await RunOne(row,false);done++;var c=(ImportCandidate)row.Tag;int retries;waitingRetries.TryGetValue(c.Source,out retries);if(c.Check.State=="waiting"&&retries<2&&!queueStop){waitingRetries[c.Source]=retries+1;await Task.Delay(2100);if(!queueStop)pending.Add(row);total=pending.Count;}}}finally{queueRunning=false;if(!IsDisposed){UpdateSelection();status.Text=queueStop?"已取消本次检查；未导入。可选择目标重新检查。":"候选检查已结束 · 选择“通过”的条目可导入；未知、失败和封面结果请看对应列。";owner.Write("candidate-queue-finished",new{completed=done,scheduled=total,cancelled=queueStop,autoImport=false,autoPlay=false});}}}
  internal void RefreshOfficialNames(Dictionary<string,NameEvidence> names){foreach(ListViewItem row in list.Items){var c=(ImportCandidate)row.Tag;OfficialNameStore.Apply(new List<ImportCandidate>{c},names);UpdateRow(row);}UpdateSelection();}
  internal void RefreshPreviewCover(string hash){foreach(ListViewItem row in list.Items){var c=(ImportCandidate)row.Tag;if(c.Check!=null&&c.Check.Sha256==hash){PreviewCovers.Attach(c.Check);c.Cover=c.Check.CoverRelative==null?null:Path.Combine(Common.Root,c.Check.CoverRelative);c.CoverReason=c.Check.CoverReason;UpdateRow(row);Thumbnail(row);}}UpdateSelection();}
  internal async Task Scan(){if(scanning||copying||queueRunning||closeRequested)return;scanning=true;queueStop=false;waitingRetries.Clear();ControlsState();status.Text="正在读取已知本地记录与有效缓存…";try{var data=await owner.ImportJob("scan",null,null);var found=Common.Json.Deserialize<List<ImportCandidate>>(Common.Json.Serialize(data["candidates"]));owner.ApplyOfficialNames(found);list.BeginUpdate();try{list.Items.Clear();thumbs.Images.Clear();foreach(var c in found)AddCandidate(c);}finally{list.EndUpdate();}owner.Write("candidate-scan-ready",new{count=found.Count,queued=found.Count(c=>c.Check==null),cached=found.Count(c=>c.Check!=null),autoImport=false});}catch(OperationCanceledException){queueStop=true;status.Text="候选读取已取消，未导入。";}catch(Exception ex){queueStop=true;status.Text="候选读取失败："+ex.Message;owner.RecordFault("check","读取本地候选","scan",ex.Message,null,()=>{if(!IsDisposed&&!closeRequested){var ignored=Scan();}});}finally{scanning=false;UpdateSelection();}if(!queueStop&&!owner.closing&&!closeRequested){queueTask=RunQueue();await queueTask;}}
  internal async Task AnalyzeSelected(){if(scanning||copying||queueRunning||Selected==null||closeRequested)return;var row=list.SelectedItems[0];if(Selected.Check!=null&&Selected.Check.State=="unknown")return;queueStop=false;queueRunning=true;done=0;total=1;queueTask=RunOne(row,true);try{await queueTask;}finally{queueRunning=false;if(!IsDisposed){UpdateSelection();status.Text=CandidateState((ImportCandidate)row.Tag);}}}
  internal async Task ImportSelected(){if(!CandidateChecks.Passed(Selected)||scanning||copying||closeRequested)return;var c=Selected;if(queueRunning)return;if(owner.closing||closeRequested)return;copying=true;ControlsState();progress.Style=ProgressBarStyle.Blocks;progress.Value=0;string outcome="";try{var data=await owner.ImportJob("copy",c,(p,b,t)=>{status.Text=p+" · "+(b/1048576.0).ToString("F1")+" / "+(t/1048576.0).ToString("F1")+" MB";progress.Value=t<=0?0:(int)Math.Min(100,b*100/t);});if(owner.closing||owner.importOperation.Cancelled)throw new OperationCanceledException();bool duplicate;owner.RegisterImport(owner.importOperation,data,out duplicate);outcome=duplicate?"相同内容已在列表中，未重复建卡。":"已入库；封面已归属管理副本，播放状态请看首页。";progress.Value=100;foreach(ListViewItem row in list.Items)UpdateRow(row);}catch(OperationCanceledException){outcome="导入已取消；未登记，临时文件已清理。";}catch(Exception ex){outcome="导入失败："+ex.Message;owner.RecordFault("save","导入所选壁纸","copy-or-register",ex.Message,c);owner.Write("local-import-failed",new{sourceId=c.Id,error=ex.Message});}finally{copying=false;if(!IsDisposed){UpdateSelection();status.Text=outcome;}}}
 }
